import { NextResponse } from 'next/server';
import { SITE_URL } from '@/lib/site';

// Legacy endpoint kept for backwards compatibility. The canonical sitemap is
// generated by `src/app/sitemap.ts` (DB-backed) and served at `/sitemap.xml`.
// This route used to serve a stale, static catalog that included noindex pages
// such as `/login` and `/checkout`; redirect it so Google only ever sees one
// authoritative sitemap.
export async function GET() {
  return NextResponse.redirect(`${SITE_URL}/sitemap.xml`, 308);
}
